    def verifier(assign):
# Validate structure and compute the hypersurface measure 2*d*s^(d-1)
# from the given vertices by extracting s via gcd of squared distances.
# Also enforce nontrivial/difficulty constraints.

# Basic checks
if not isinstance(assign, dict):
    # invalid structure
    return (False, None)  # invalid
if 'dimension' not in assign or 'num_points' not in assign or 'points' not in assign:
    return (False, None)  # missing keys
d = assign['dimension']
m = assign['num_points']
pts = assign['points']
if not isinstance(d, int) or d < 3:
    return (False, None)  # dimension must be at least 3
if not isinstance(m, int) or m < 3:
    return (False, None)  # at least 3 points required
if not isinstance(pts, list) or len(pts) != m:
    return (False, None)  # points length mismatch
# Check points are integer-coordinate vectors of length d
for p in pts:
    if not isinstance(p, list) or len(p) != d:
        return (False, None)  # each point must be a list of length d
    for x in p:
        if not isinstance(x, int):
            return (False, None)  # require integer coordinates to avoid float gcd issues

# Compute all pairwise squared distances
distsq = []
for i in range(m):
    for j in range(i+1, m):
        dsq = 0
        for k in range(d):
            diff = pts[i][k] - pts[j][k]
            dsq += diff * diff
        if dsq == 0:
            return (False, None)  # points must be distinct
        distsq.append(dsq)

# gcd over all squared distances
def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)
g = 0
for val in distsq:
    g = gcd(g, val)
if g <= 0:
    return (False, None)  # invalid gcd

# Check that g is a perfect square and extract s
# integer square root check
s = int(g ** 0.5)
if s * s != g:
    return (False, None)  # must be square so that s is integer; enforces gcd of Hamming distances is 1

# Verify all pairwise distances are integer multiples of s^2 in [1, d]
multipliers = []
for val in distsq:
    if val % g != 0:
        return (False, None)  # not a multiple of g
    k = val // g
    if k < 1 or k > d:
        return (False, None)  # outside hypercube Hamming range
    multipliers.append(k)
# Enforce difficulty: gcd of multipliers must be 1; at least two distinct values
gm = 0
for k in multipliers:
    gm = gcd(gm, k)
if gm != 1:
    return (False, None)  # would allow trivial scaling ambiguity
if len(set(multipliers)) < 2:
    return (False, None)  # too trivial; all distances equal

# Additional structural check (consistent with signed permutation orientation):
# For every pair, each coordinate difference should be in {0, ±s}.
# This is satisfied for our generated instances and rules out malformed inputs.
for i in range(m):
    for j in range(i+1, m):
        for k in range(d):
            diff = pts[i][k] - pts[j][k]
            if diff not in (0, s, -s):
                return (False, None)  # differences per coordinate must be 0 or ±s

# Compute hypersurface measure: 2*d*s^(d-1)
answer = 2 * d * (s ** (d - 1))
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

